def gcd(a, b):
    while b:
        a, b = b, a % b
    return a
def main():
    numerator_line = input().strip()
    vinculum_line = input().strip()
    denominator_line = input().strip()
    numerator = int(numerator_line.strip())
    denominator = int(denominator_line.strip())
    common_divisor = gcd(abs(numerator), abs(denominator))
    reduced_numerator = numerator // common_divisor
    reduced_denominator = denominator // common_divisor
    if reduced_numerator * reduced_denominator < 0:
        reduced_numerator = -abs(reduced_numerator)
        reduced_denominator = abs(reduced_denominator)
    else:
        reduced_numerator = abs(reduced_numerator)
        reduced_denominator = abs(reduced_denominator)
    if reduced_denominator == 1:
        print(reduced_numerator)
    else:
        print(f"{reduced_numerator}/{reduced_denominator}")
if __name__ == "__main__":
    main()

solution:
def parse_input():
    import sys
    input = sys.stdin.read
    data = input().splitlines()

    n, m = map(int, data[0].split())
    metadata = data[1].split()
    measurements = [line.split() for line in data[2:]]

    return n, m, metadata, measurements

def process_measurements(measurements):
    processed_data = []
    for measurement in measurements:
        if '-' in measurement:
            processed_data.append(None)
        else:
            temp, wind_dir, wind_speed, humidity = measurement
            processed_data.append((float(temp), int(wind_dir), float(wind_speed), int(humidity)))
    return processed_data

def predict_next_value(data, index, default_value=None):
    if index < len(data) and data[index] is not None:
        return data[index]
    elif index > 0:
        prev_value = data[index - 1]
        if prev_value is not None:
            return prev_value
    return default_value

def generate_predictions(processed_data, m):
    predictions = []
    for i in range(m):
        next_index = len(processed_data) + i
        temp = predict_next_value(processed_data, next_index, default_value='-')
        wind_dir = predict_next_value(processed_data, next_index, default_value='-')
        wind_speed = predict_next_value(processed_data, next_index, default_value='-')
        humidity = predict_next_value(processed_data, next_index, default_value='-')
        predictions.append((temp, wind_dir, wind_speed, humidity))
    return predictions

def print_predictions(predictions):
    for prediction in predictions:
        print(f"{prediction[0]} {prediction[1]} {prediction[2]} {prediction[3]}")

def main():
    n, m, metadata, measurements = parse_input()
    processed_data = process_measurements(measurements)
    predictions = generate_predictions(processed_data, m)
    print_predictions(predictions)

if __name__ == "__main__":
    main()

